using System.Linq;
using Microsoft.CodeAnalysis;
using Rask.Generators.Shared;

namespace Rask.Batteries.Generators;

/// <summary>Whether a typed id over a Guid makes its own key with a <c>New()</c>.</summary>
internal static class TypedIdNew
{
    // New() is generated by the Rask package's TypedIdGenerator, which these generators cannot see, so its rule is asked —
    // or the id is compiled into a referenced assembly, or written by hand, with a public static New() of its own
    public static bool Has(ITypeSymbol idType) =>
        TypedIdShape.Of(idType) == TypedIdValue.Guid ||
        idType.GetMembers("New").OfType<IMethodSymbol>().Any(static m =>
            m is { IsStatic: true, Parameters.Length: 0, DeclaredAccessibility: Accessibility.Public });
}
